// SPDX-License-Identifier: CC0-1.0
// 計測用。入力生成・独立の全要素表による照合は各操作の計測外。
#include FENWICK2D_LIBRARY
#include <algorithm>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>
#include <sys/resource.h>

struct Point { int row, col; std::int64_t value; };
struct Query { int row_l, col_l, row_r, col_r; };
using Clock = std::chrono::steady_clock;
static std::uint64_t random_state = UINT64_C(0x36c798e1a513db07);
static std::uint64_t rng() {
  random_state ^= random_state << 7;
  random_state ^= random_state >> 9;
  return random_state;
}
static std::int64_t elapsed(Clock::time_point begin) {
  return std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now() - begin).count();
}
int main(int argc, char** argv) {
  const std::string name = argc > 1 ? argv[1] : "row8192";
  int n = 1, m = 8192, updates = 3'000'000, queries = 100'000, singles = 200'000;
  if (name == "row8192") {}
  else if (name == "row32768") m = 32768;
  else if (name == "row262144") { m = 262144; updates = 2'000'000; }
  else if (name == "row1000000") { m = 1'000'000; updates = 100'000; }
  else if (name == "rows32_32768") { n = 32; m = 32768; updates = 100'000; }
  else { std::fprintf(stderr, "unknown case: %s\n", name.c_str()); return 1; }
  const bool smoke = argc > 2 && std::string(argv[2]) == "--smoke";
  if (smoke) { updates = 300; queries = 300; singles = 300; }

  std::vector<Point> points;
  points.reserve(static_cast<std::size_t>(updates));
  std::vector<Query> rectangles;
  rectangles.reserve(static_cast<std::size_t>(queries));
  std::vector<Point> positions;
  positions.reserve(static_cast<std::size_t>(singles));
  std::vector<std::int64_t> reference(static_cast<std::size_t>(n) * m);
  std::int64_t original_total = 0;
  for (int k = 0; k < updates; ++k) {
    const int row = static_cast<int>(rng() % static_cast<std::uint64_t>(n));
    const int col = static_cast<int>(rng() % static_cast<std::uint64_t>(m));
    const std::int64_t value = static_cast<std::int64_t>(rng() % 7) - 3;
    points.push_back({row, col, value});
    reference[static_cast<std::size_t>(row) * m + col] += value;
    original_total += value;
  }
  for (int k = 0; k < queries; ++k) {
    // n=1でも全ての照会が空にならないよう、行方向は非空区間とする。
    const int first = static_cast<int>(rng() % static_cast<std::uint64_t>(n));
    const int last = first + 1 + static_cast<int>(rng() % static_cast<std::uint64_t>(n - first));
    int l = static_cast<int>(rng() % (static_cast<std::uint64_t>(m) + 1));
    int r = static_cast<int>(rng() % (static_cast<std::uint64_t>(m) + 1));
    if (l > r) std::swap(l, r);
    rectangles.push_back({first, l, last, r});
  }
  for (int k = 0; k < singles; ++k) {
    const int row = static_cast<int>(rng() % static_cast<std::uint64_t>(n));
    const int col = static_cast<int>(rng() % static_cast<std::uint64_t>(m));
    positions.push_back({row, col, static_cast<std::int64_t>(rng() % 63) - 31});
  }
  // ライブラリを使わない累積表。計測後のchecksumを検証する。
  const std::size_t stride = static_cast<std::size_t>(m) + 1;
  std::vector<std::int64_t> prefixes((static_cast<std::size_t>(n) + 1) * stride);
  for (int row = 0; row < n; ++row)
    for (int col = 0; col < m; ++col) {
      const std::size_t k = (static_cast<std::size_t>(row) + 1) * stride + col + 1;
      prefixes[k] = reference[static_cast<std::size_t>(row) * m + col]
                  + prefixes[k - 1] + prefixes[k - stride] - prefixes[k - stride - 1];
    }
  const auto independent_sum = [&](int row, int col) { return prefixes[static_cast<std::size_t>(row) * stride + col]; };
  std::int64_t expected_rectangle = 0, expected_prefix = 0, expected_get = 0;
  for (const auto& q : rectangles) {
    expected_rectangle += independent_sum(q.row_r, q.col_r) - independent_sum(q.row_l, q.col_r)
                        - independent_sum(q.row_r, q.col_l) + independent_sum(q.row_l, q.col_l);
    expected_prefix += independent_sum(q.row_r, q.col_r);
  }
  for (const auto& q : positions) expected_get += reference[static_cast<std::size_t>(q.row) * m + q.col];
  std::int64_t expected_set_total = original_total;
  for (const auto& q : positions) {
    auto& value = reference[static_cast<std::size_t>(q.row) * m + q.col];
    expected_set_total += q.value - value;
    value = q.value;
  }

  DynamicFenwickTree2D<std::int64_t> bit(n, m);
  auto begin = Clock::now();
  for (const auto& p : points) bit.add(p.row, p.col, p.value);
  const auto add_ns = elapsed(begin);
  const auto nodes = bit.stored_nodes();
  if (bit.sum_all() != original_total) return 2;
  std::int64_t rectangle_checksum = 0, prefix_checksum = 0, get_checksum = 0;
  begin = Clock::now();
  for (const auto& q : rectangles) rectangle_checksum += bit.sum(q.row_l, q.col_l, q.row_r, q.col_r);
  const auto rectangle_ns = elapsed(begin);
  begin = Clock::now();
  for (const auto& q : rectangles) prefix_checksum += bit.sum(q.row_r, q.col_r);
  const auto prefix_ns = elapsed(begin);
  begin = Clock::now();
  for (const auto& q : positions) get_checksum += bit.get(q.row, q.col);
  const auto get_ns = elapsed(begin);
  if (nodes != bit.stored_nodes() || rectangle_checksum != expected_rectangle || prefix_checksum != expected_prefix || get_checksum != expected_get) return 3;
  begin = Clock::now();
  for (const auto& q : positions) bit.set(q.row, q.col, q.value);
  const auto set_ns = elapsed(begin);
  const auto set_nodes = bit.stored_nodes();
  if (bit.sum_all() != expected_set_total) return 4;
  begin = Clock::now();
  auto copy = bit;
  const auto copy_ns = elapsed(begin);
  if (copy.sum_all() != expected_set_total || copy.stored_nodes() != set_nodes) return 5;
  begin = Clock::now();
  bit.clear();
  const auto clear_ns = elapsed(begin);
  if (bit.stored_nodes() != 0 || bit.sum_all() != 0) return 6;
  begin = Clock::now();
  for (const auto& p : points) bit.add(p.row, p.col, p.value);
  const auto refill_ns = elapsed(begin);
  if (bit.sum_all() != original_total || bit.stored_nodes() != nodes) return 7;
  const std::int64_t checksum = rectangle_checksum + prefix_checksum + get_checksum + expected_set_total + original_total;
  struct rusage usage{};
  getrusage(RUSAGE_SELF, &usage);
  std::printf("{\"case\":\"%s\",\"rows\":%d,\"cols\":%d,\"updates\":%d,\"queries\":%d,\"single_queries\":%d,\"add_ns\":%jd,\"rectangle_ns\":%jd,\"prefix_ns\":%jd,\"get_ns\":%jd,\"set_ns\":%jd,\"copy_ns\":%jd,\"clear_ns\":%jd,\"refill_ns\":%jd,\"nodes\":%zu,\"set_nodes\":%zu,\"checksum\":%jd,\"peak_rss_kib\":%jd,\"reference\":\"independent_dense_prefix_and_array\",\"status\":\"pass\"}\n",
    name.c_str(), n, m, updates, queries, singles,
    static_cast<std::intmax_t>(add_ns), static_cast<std::intmax_t>(rectangle_ns),
    static_cast<std::intmax_t>(prefix_ns), static_cast<std::intmax_t>(get_ns),
    static_cast<std::intmax_t>(set_ns), static_cast<std::intmax_t>(copy_ns),
    static_cast<std::intmax_t>(clear_ns), static_cast<std::intmax_t>(refill_ns),
    nodes, set_nodes, static_cast<std::intmax_t>(checksum), static_cast<std::intmax_t>(usage.ru_maxrss));
}

