#include <array>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstddef>
#include <cstdio>
#include <cstdlib>
#include FENWICK_SOURCE
using I=std::int64_t;using Bit=DynamicFenwickTree2D<I>;
struct Point{int column;I value;};
#if defined(__GNUC__) || defined(__clang__)
[[gnu::noinline]]
#endif
static std::uint64_t consume(const Bit& bit){return static_cast<std::uint64_t>(bit.sum_all())+static_cast<std::uint64_t>(bit.stored_nodes());}
int main(int argc,char**argv){
 if(argc<3)return 2;
 const int count=std::atoi(argv[1]),width=std::atoi(argv[2]),iterations=argc>3?std::atoi(argv[3]):10000;
 if(count<1||count>128||width<128||iterations<1)return 3;
 std::array<Point,128> points{};I expected=0;
 for(int j=0;j<count;++j){points[j]={static_cast<int>((std::uint32_t(j)*7919U+17U)%static_cast<std::uint32_t>(width)),I(j%17)+1};expected+=points[j].value;}
 Bit prepared(1,width);for(int j=0;j<count;++j)prepared.add(0,points[j].column,points[j].value);
 if(prepared.sum_all()!=expected)return 4;
 std::uint64_t copy_checksum=0,refill_checksum=0;
 const auto copy_begin=std::chrono::steady_clock::now();
 for(int rep=0;rep<iterations;++rep){Bit copied=prepared;std::atomic_signal_fence(std::memory_order_seq_cst);copy_checksum+=consume(copied);}
 const auto copy_end=std::chrono::steady_clock::now();
 Bit reusable=prepared;reusable.clear();for(int j=0;j<count;++j)reusable.add(0,points[j].column,points[j].value);
 const auto refill_begin=std::chrono::steady_clock::now();
